package main

import("encoding/json";"fmt";"net/http";"strconv";"strings")

func sqlIdent(s string) string { return `"`+strings.ReplaceAll(s,`"`,`""`)+`"` }
func adminSchemaDataHandler(w http.ResponseWriter,r *http.Request){
 if !requireAdmin(w,r){return}; if r.Method!=http.MethodGet{w.WriteHeader(405);return}
 w.Header().Set("Content-Type","application/json")
 table:=strings.TrimSpace(r.URL.Query().Get("table"))
 if table==""{
  rows,e:=userDB.Query(`SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name`);if e!=nil{http.Error(w,e.Error(),500);return};defer rows.Close(); tables:=[]string{};for rows.Next(){var t string;if rows.Scan(&t)==nil{tables=append(tables,t)}};json.NewEncoder(w).Encode(map[string]any{"status":"success","schema":"public","tables":tables});return
 }
 var exists bool; if e:=userDB.QueryRow(`SELECT EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name=$1 AND table_type='BASE TABLE')`,table).Scan(&exists);e!=nil||!exists{http.Error(w,"Table not found",404);return}
 cr,e:=userDB.Query(`SELECT column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position`,table);if e!=nil{http.Error(w,e.Error(),500);return};defer cr.Close();type Col struct{Name string `json:"name"`;Type string `json:"type"`;Nullable string `json:"nullable"`};cols:=[]Col{};for cr.Next(){var c Col;if cr.Scan(&c.Name,&c.Type,&c.Nullable)==nil{cols=append(cols,c)}}
 limit:=200;if n,e:=strconv.Atoi(r.URL.Query().Get("limit"));e==nil&&n>0&&n<=500{limit=n};q:=fmt.Sprintf("SELECT * FROM %s LIMIT %d",sqlIdent(table),limit);rr,e:=userDB.Query(q);if e!=nil{http.Error(w,e.Error(),500);return};defer rr.Close();names,_:=rr.Columns();data:=[]map[string]any{};for rr.Next(){vals:=make([]any,len(names));ptrs:=make([]any,len(names));for i:=range vals{ptrs[i]=&vals[i]};if rr.Scan(ptrs...)!=nil{continue};row:=map[string]any{};for i,n:=range names{v:=vals[i];if b,ok:=v.([]byte);ok{if len(b)>4096{v=string(b[:4096])+" … [truncated]"}else{v=string(b)}};row[n]=v};data=append(data,row)}
 json.NewEncoder(w).Encode(map[string]any{"status":"success","schema":"public","table":table,"columns":cols,"rows":data,"row_limit":limit})
}
func adminSchemaPageHandler(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodGet{w.WriteHeader(405);return};w.Header().Set("Content-Type","text/html; charset=utf-8");w.Header().Set("Cache-Control","no-store");_,_=w.Write([]byte(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>88Task • Public Schema</title><style>body{font:14px system-ui;margin:0;color:#111}.wrap{max-width:1500px;margin:auto;padding:20px}.top{display:flex;justify-content:space-between;align-items:center;gap:10px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.controls select,.controls input,.btn{padding:9px;border:1px solid #ddd;border-radius:8px;background:#fff}.btn{font-weight:700}.card{border:1px solid #ddd;border-radius:12px;padding:14px;margin-top:14px;overflow:auto}.muted{color:#777}.cols{display:flex;gap:8px;flex-wrap:wrap}.pill{border:1px solid #ddd;border-radius:8px;padding:6px 9px;font-size:12px}.tablewrap{overflow:auto}table{border-collapse:collapse;min-width:100%;white-space:nowrap}th,td{padding:8px;border-bottom:1px solid #eee;text-align:left;max-width:360px;overflow:hidden;text-overflow:ellipsis}th{font-size:12px;color:#666;position:sticky;top:0;background:#fff}</style></head><body><main class="wrap"><div class="top"><div><h1>Public Schema</h1><div class="muted">Database-style viewer • public schema • read only</div></div><a class="btn" href="/admin">Dashboard</a></div><div class="controls"><select id="tables"><option>Loading tables…</option></select><input id="limit" type="number" min="1" max="500" value="200"><button class="btn" onclick="loadTable()">Refresh</button></div><div id="info" class="card">Select a table.</div><div id="data" class="card tablewrap"></div></main><script>const key='admin_token';const api='/admin/schema/data';function esc(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}async function req(url){let r=await fetch(url,{headers:{'X-Admin-Token':sessionStorage.getItem(key)}});if(r.status===401){location.href='/admin';return null}return r.json()}async function init(){let d=await req(api);if(!d)return;let s=document.getElementById('tables');s.innerHTML=(d.tables||[]).map(t=>'<option>'+esc(t)+'</option>').join('');if(d.tables?.length)loadTable()}async function loadTable(){let t=document.getElementById('tables').value;if(!t)return;let l=document.getElementById('limit').value||200;let d=await req(api+'?table='+encodeURIComponent(t)+'&limit='+encodeURIComponent(l));if(!d)return;document.getElementById('info').innerHTML='<b>public.'+esc(d.table)+'</b><div class="cols">'+(d.columns||[]).map(c=>'<span class="pill">'+esc(c.name)+' · '+esc(c.type)+' · '+esc(c.nullable)+'</span>').join('')+'</div><div class="muted">Showing up to '+d.row_limit+' rows</div>';let cols=d.columns||[],rows=d.rows||[];document.getElementById('data').innerHTML='<table><thead><tr>'+cols.map(c=>'<th>'+esc(c.name)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td title="'+esc(r[c.name])+'">'+esc(r[c.name])+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}init()</script></body></html>`))}
func init(){http.HandleFunc("/admin/schema",adminSchemaPageHandler);http.HandleFunc("/admin/schema/data",adminSchemaDataHandler)}
